// GCEA service worker. Generated by `vite build` (see vite.config.js): the build replaces
// the two placeholders with a content hash and the list of files to precache.
const VERSION = '__GCEA_VERSION__';
const PRECACHE_URLS = __GCEA_PRECACHE__;
const CACHE = `gcea-${VERSION}`;
const RUNTIME = `gcea-runtime-${VERSION}`;
const FONT_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com'];

self.addEventListener('install', event => {
  // Every lesson is precached so the whole course works offline after the first visit.
  // A new version then waits until the page asks it to take over (update banner).
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(PRECACHE_URLS)));
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys
        .filter(key => key.startsWith('gcea') && key !== CACHE && key !== RUNTIME)
        .map(key => caches.delete(key))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', event => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);

  // Pages: network first so a new deployment shows at once; the cached app shell offline.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() => caches.match('/', { cacheName: CACHE }).then(hit => hit || Response.error()))
    );
    return;
  }

  // Own files: cache first. Built file names change whenever their content changes.
  if (url.origin === self.location.origin) {
    event.respondWith(caches.match(request).then(hit => hit || fetchAndCache(request)));
    return;
  }

  // Google Fonts: serve from cache, refresh in the background.
  if (FONT_HOSTS.includes(url.hostname)) {
    event.respondWith(staleWhileRevalidate(request));
  }
});

async function fetchAndCache(request) {
  const response = await fetch(request);
  if (response.ok && response.type === 'basic') {
    const cache = await caches.open(RUNTIME);
    cache.put(request, response.clone());
  }
  return response;
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then(response => {
      if (response.ok || response.type === 'opaque') cache.put(request, response.clone());
      return response;
    })
    .catch(() => cached || Response.error());
  return cached || network;
}
